mapper.select:
select
con.Con_Name as conName,
con.Con_Code as conCode,
sd.D_Name as dName,

mn.*
from OA_WorkOrder mn
left join Con_Contract con on con.Con_Id=mn.Con_Id

left join SYS_Department sd on sd.D_Id=mn.D_Id
${params.authSql}

    and mn.Te_Id = #{params.teId}


    and mn.P_Id=#{params.pId}


    and mn.Wo_Type = #{params.woType}


    and mn.Wo_Priority = #{params.woPriority}


    and mn.Wo_State = #{params.woState}


    and mn.Wo_Resolved_State = #{params.woResolvedState}


    and pro.Wo_Title like concat('%',#{params.woTitle},'%')


    and pro.Wo_Code like concat('%',#{params.woCode},'%')


    
        
            and likePname(#{params.pName},pro.P_Id)=true
        
        
            and pro.P_Name like concat('%',#{params.pName},'%')
        
    


    and con.Con_Name like concat('%',#{params.conName},'%')


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Wo_Create_Time desc
